"""Deterministic JSONL event generator + schema validator + run logger.

Usage:
  python3 subtask1_generator.py --seed <int> --count <n> --schema <path> \
      --mode <append|overwrite> --out data/events.jsonl

Determinism: for a fixed (seed, schema) the emitted records are byte-identical
on every run (ids/timestamps derived from the seed, never wall clock).
"""
import argparse
import datetime as _dt
import hashlib
import json
import os
import random
import sys

LOG_PATH = os.path.join("logs", "gen.log")
BASE_EPOCH = 1_700_000_000  # fixed anchor for deterministic timestamps


def load_schema(path):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def _hex(seed, index, field):
    return hashlib.sha256(f"{seed}:{index}:{field}".encode()).hexdigest()


def _uuid(seed, index):
    h = _hex(seed, index, "id")
    return f"{h[0:8]}-{h[8:12]}-{h[12:16]}-{h[16:20]}-{h[20:32]}"


def _gen_value(spec, rng, seed, index, field):
    fmt = spec.get("format")
    typ = spec.get("type", "string")
    if fmt == "uuid":
        return _uuid(seed, index)
    if fmt == "date-time":
        ts = BASE_EPOCH + index * 60 + (seed % 86400)
        return _dt.datetime.fromtimestamp(ts, _dt.timezone.utc).isoformat()
    if "enum" in spec:
        return rng.choice(spec["enum"])
    if typ == "integer":
        return rng.randint(spec.get("minimum", 0), spec.get("maximum", 100))
    if typ == "number":
        lo = spec.get("minimum", 0.0)
        hi = spec.get("maximum", 1.0)
        return round(rng.uniform(lo, hi), 4)
    if typ == "boolean":
        return rng.random() < 0.5
    if typ == "array":
        n = rng.randint(spec.get("minItems", 0), spec.get("maxItems", 3))
        item = spec.get("items", {"type": "string"})
        return [_gen_value(item, rng, seed, index, f"{field}[{i}]") for i in range(n)]
    length = spec.get("minLength", 6)
    return "".join(rng.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(length))


def generate_records(schema, seed, count):
    props = schema.get("properties", {})
    records = []
    for index in range(count):
        rng = random.Random(f"{seed}:{index}".encode())
        rec = {name: _gen_value(spec, rng, seed, index, name) for name, spec in props.items()}
        records.append(rec)
    return records


def _type_ok(value, typ):
    return {
        "string": isinstance(value, str),
        "integer": isinstance(value, int) and not isinstance(value, bool),
        "number": isinstance(value, (int, float)) and not isinstance(value, bool),
        "boolean": isinstance(value, bool),
        "array": isinstance(value, list),
    }.get(typ, True)


def validate_record(rec, schema):
    props = schema.get("properties", {})
    for name in schema.get("required", []):
        if name not in rec:
            return False
    for name, spec in props.items():
        if name not in rec:
            continue
        val = rec[name]
        if not _type_ok(val, spec.get("type", "string")):
            return False
        if "enum" in spec and val not in spec["enum"]:
            return False
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            if "minimum" in spec and val < spec["minimum"]:
                return False
            if "maximum" in spec and val > spec["maximum"]:
                return False
        if isinstance(val, list):
            if not (spec.get("minItems", 0) <= len(val) <= spec.get("maxItems", len(val))):
                return False
            item = spec.get("items", {})
            if not all(_type_ok(v, item.get("type", "string")) for v in val):
                return False
    return True


def write_log(entry):
    os.makedirs(os.path.dirname(LOG_PATH), exist_ok=True)
    with open(LOG_PATH, "a", encoding="utf-8") as fh:
        fh.write(json.dumps(entry, sort_keys=[secret redacted]


def main(argv=None):
    ap = argparse.ArgumentParser(description="Deterministic JSONL event generator")
    ap.add_argument("--seed", type=int, required=True)
    ap.add_argument("--count", type=int, required=True)
    ap.add_argument("--schema", required=True)
    ap.add_argument("--mode", choices=["append", "overwrite"], default="overwrite")
    ap.add_argument("--out", default=os.path.join("data", "events.jsonl"))
    args = ap.parse_args(argv)

    schema = load_schema(args.schema)
    records = generate_records(schema, args.seed, args.count)
    valid = sum(1 for r in records if validate_record(r, schema))

    os.makedirs(os.path.dirname(args.out) or ".", exist_ok=True)
    lines = [json.dumps(r, sort_keys=True, separators=(",", ":")) for r in records]
    with open(args.out, "w" if args.mode == "overwrite" else "a", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + ("\n" if lines else ""))

    meta_out = os.path.join(os.path.dirname(args.out) or ".", f"metadata_seed{args.seed}.jsonl")
    with open(meta_out, "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + ("\n" if lines else ""))

    entry = {
        "timestamp": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        "seed": args.seed,
        "count": args.count,
        "schema": args.schema,
        "mode": args.mode,
        "out": args.out,
        "valid": valid,
        "total": len(records),
    }
    write_log(entry)
    print(json.dumps(entry, sort_keys=[secret redacted]
    return 0 if valid == len(records) else 1


if __name__ == "__main__":
    sys.exit(main())

