"""Orchestrator: feeds subtask1 events as tasks to socket workers, persisting
task state through the subtask2 transactional KV store.

Design:
  * One TCP loopback server. Workers pull tasks, process, report completion.
  * Tasks are partitioned round-robin across worker slots (task i -> slot i % N),
    so an evenly-sized pool finishes with a balanced workload.
  * A worker that disconnects while holding a task (simulated crash) has that
    task requeued to its own slot and re-dispatched -> retry.
  * Every status change is written to the KV store, so a restarted orchestrator
    rebuilds pending/done state from disk.
"""
import argparse
import datetime as _dt
import json
import os
import socket
import sys
import threading
from collections import deque

_HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(_HERE, "kv"))
from subtask2_kvstore import KVStore  # noqa: E402

DEFAULT_STATE_DIR = os.path.join(_HERE, "kv", "orch_state")
DEFAULT_EVENTS = os.path.join(_HERE, "data", "events.jsonl")
LOG_PATH = os.path.join("logs", "orchestrator.log")
TASK_PREFIX = "task:"


def log_line(path, msg):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    ts = _dt.datetime.now(_dt.timezone.utc).isoformat()
    with open(path, "a", encoding="utf-8") as fh:
        fh.write("%s %s\n" % (ts, msg))


def load_tasks(events_path, count):
    events = []
    if os.path.exists(events_path):
        with open(events_path, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line:
                    events.append(json.loads(line))
    if not events:
        events = [{"id": "empty", "event_type": "noop"}]
    return [events[i % len(events)] for i in range(count)]


def _slot_of(worker_id):
    try:
        return int(str(worker_id).lstrip("wW"))
    except (TypeError, ValueError):
        return 0


class Orchestrator:
    def __init__(self, tasks, workers, state_dir=DEFAULT_STATE_DIR,
                 host="127.0.0.1", port=0, log_path=LOG_PATH):
        self.workers = max(1, int(workers))
        self.state_dir = state_dir
        self.host = host
        self.port = port
        self.log_path = log_path
        self.store = KVStore(state_dir, snapshot_interval=0, fsync=False)

        self._lock = threading.Lock()
        self._tasks = {}
        self._status = {}
        self._attempts = {}
        self._inflight = {}
        self._queues = {s: deque() for s in range(self.workers)}
        self.completed_by_worker = {}
        self.crash_requeues = 0      # forced failures observed
        self.retried_completed = 0   # tasks recovered after a crash

        self._stop = threading.Event()
        self._srv = None
        self._thread = None
        self._load(tasks)

    # ---- state ----------------------------------------------------------
    def _persist(self, tid):
        tx = self.store.begin_tx()
        self.store.put(tx, TASK_PREFIX + tid, {
            "id": tid,
            "payload": self._tasks[tid],
            "status": self._status[tid],
            "attempts": self._attempts[tid],
            "worker": self._inflight.get(tid),
        })
        self.store.commit(tx)

    def _load(self, tasks):
        saved = {}
        for key, val in self.store.items():
            [secret redacted]
                saved[key[len(TASK_PREFIX):[secret redacted]
        for i, payload in enumerate(tasks):
            tid = "task-%d" % i
            self._tasks[tid] = payload
            self._attempts[tid] = 0
            self._status[tid] = "pending"
            if tid in saved:
                st = saved[tid]
                self._status[tid] = st.get("status", "pending")
                self._attempts[tid] = st.get("attempts", 0)
                if st.get("status") == "done" and st.get("worker"):
                    w = st["worker"]
                    self.completed_by_worker[w] = self.completed_by_worker.get(w, 0) + 1
            if self._status[tid] != "done":
                self._status[tid] = "pending"
                self._queues[i % self.workers].append(tid)
        log_line(self.log_path, "loaded %d tasks, %d pending, %d done" % (
            len(self._tasks),
            sum(len(q) for q in self._queues.values()),
            sum(1 for s in self._status.values() if s == "done")))

    # ---- dispatch -------------------------------------------------------
    def _claim(self, worker):
        slot = _slot_of(worker)
        if slot not in self._queues:
            slot = 0
        with self._lock:
            q = self._queues[slot]
            if q:
                tid = q.popleft()
                self._status[tid] = "inflight"
                self._inflight[tid] = worker
                self._persist(tid)
                return {"id": tid, "payload": self._tasks[tid]}
            if self._inflight or any(self._queues.values()):
                return "wait"
            return None

    def _complete(self, tid, worker):
        with self._lock:
            if tid is None or self._status.get(tid) != "inflight":
                return
            self._status[tid] = "done"
            self._inflight.pop(tid, None)
            if self._attempts[tid] > 0:
                self.retried_completed += 1
            self.completed_by_worker[worker] = self.completed_by_worker.get(worker, 0) + 1
            self._persist(tid)

    def _requeue(self, tid, worker):
        with self._lock:
            if tid is None or self._status.get(tid) != "inflight":
                return
            self._attempts[tid] += 1
            self._status[tid] = "pending"
            self._inflight.pop(tid, None)
            self._queues[_slot_of(worker) if _slot_of(worker) in self._queues else 0].appendleft(tid)
            self.crash_requeues += 1
            self._persist(tid)
            log_line(self.log_path, "requeued %s after worker %s disconnect (attempt %d)" % (
                tid, worker, self._attempts[tid]))

    # ---- server ---------------------------------------------------------
    def _handle(self, conn):
        worker = None
        current = None
        with conn:
            fh = conn.makefile("rwb")
            try:
                for raw in fh:
                    try:
                        req = json.loads(raw.decode())
                    except Exception:
                        fh.write(b'{"ok": false, "error": "bad json"}\n')
                        fh.flush()
                        continue
                    cmd = req.get("cmd")
                    try:
                        if cmd == "register":
                            worker = req.get("worker")
                            resp = {"ok": True}
                        elif cmd == "get_task":
                            task = self._claim(worker)
                            if task is None:
                                resp = {"ok": True, "done": True}
                            elif task == "wait":
                                resp = {"ok": True, "wait": True}
                            else:
                                current = task["id"]
                                resp = {"ok": True, "task": task}
                        elif cmd == "complete":
                            self._complete(req.get("task"), worker)
                            current = None
                            resp = {"ok": True}
                        else:
                            resp = {"ok": False, "error": "unknown cmd"}
                    except Exception as exc:
                        resp = {"ok": False, "error": str(exc)}
                    fh.write((json.dumps(resp) + "\n").encode())
                    fh.flush()
            except Exception:
                pass
            finally:
                if current is not None:
                    self._requeue(current, worker)

    def _accept_loop(self):
        while not self._stop.is_set():
            try:
                conn, _ = self._srv.accept()
            except socket.timeout:
                continue
            except OSError:
                break
            threading.Thread(target=self._handle, args=(conn,), daemon=True).start()

    def start(self):
        self._srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._srv.bind((self.host, self.port))
        self._srv.listen(64)
        self.host, self.port = self._srv.getsockname()
        self._srv.settimeout(0.2)
        self._thread = threading.Thread(target=self._accept_loop, daemon=True)
        self._thread.start()
        log_line(self.log_path, "listening %s:%d workers=%d tasks=%d" % (
            self.host, self.port, self.workers, len(self._tasks)))
        return self.host, self.port

    def stop(self):
        self._stop.set()
        try:
            self._srv.close()
        except Exception:
            pass
        self.store.close()

    # ---- introspection --------------------------------------------------
    def done_count(self):
        with self._lock:
            return sum(1 for s in self._status.values() if s == "done")

    def all_done(self):
        with self._lock:
            return not self._inflight and not any(self._queues.values())


def main(argv=None):
    ap = argparse.ArgumentParser(description="Task orchestrator (subtask3)")
    ap.add_argument("--events", default=DEFAULT_EVENTS)
    ap.add_argument("--tasks", type=int, default=100)
    ap.add_argument("--workers", type=int, default=4)
    ap.add_argument("--state-dir", default=DEFAULT_STATE_DIR)
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--port", type=int, default=9998)
    ap.add_argument("--log", default=LOG_PATH)
    args = ap.parse_args(argv)

    orch = Orchestrator(load_tasks(args.events, args.tasks), args.workers,
                        state_dir=args.state_dir, host=args.host, port=args.port,
                        log_path=args.log)
    host, port = orch.start()
    print("orchestrator_listening=%s:%d" % (host, port))
    try:
        while not orch.all_done():
            import time
            time.sleep(0.1)
    except KeyboardInterrupt:
        [secret redacted]
    orch.stop()
    print("tasks_done=%d" % orch.done_count())
    return 0


if __name__ == "__main__":
    sys.exit(main())

